import{_ as a,o as t,c as n,a6 as s}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"字段行语法","description":"field-name、field-value、OWS 处理、重复字段合并与 list-based 字段的通用规则。","frontmatter":{"title":"字段行语法","description":"field-name、field-value、OWS 处理、重复字段合并与 list-based 字段的通用规则。","source":"https://daiw.org/manual/http11/field-syntax"},"headers":[],"relativePath":"manual/computer-programming/http11/field-syntax.md","filePath":"manual/computer-programming/http11/field-syntax.md"}'),o={name:"manual/computer-programming/http11/field-syntax.md"};function d(i,e,r,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="字段行语法" tabindex="-1">字段行语法 <a class="header-anchor" href="#字段行语法" aria-label="Permalink to &quot;字段行语法&quot;">​</a></h1><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>field-line  = field-name &quot;:&quot; OWS field-value OWS</span></span>
<span class="line"><span>field-name  = token</span></span>
<span class="line"><span>field-value = *field-content</span></span>
<span class="line"><span>field-content = field-vchar [ 1*( SP / HTAB / field-vchar ) field-vchar ]</span></span>
<span class="line"><span>field-vchar   = VCHAR / obs-text</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>要点逐条：</p><ul><li>冒号<strong>前不得有任何空白</strong>。<code>Host : x</code> 必须被拒（400），代理必须丢弃该报文而非转发。</li><li>冒号后的 <code>OWS</code> 与值尾的 <code>OWS</code> 在解析时<strong>必须剥除</strong>，不属于值。</li><li>值<strong>内部</strong>的空白保留。</li><li>值可以为空。</li></ul><h2 id="field-name" tabindex="-1">field-name <a class="header-anchor" href="#field-name" aria-label="Permalink to &quot;field-name&quot;">​</a></h2><ul><li><strong>大小写不敏感</strong>：<code>Content-Type</code>、<code>content-type</code>、<code>CONTENT-TYPE</code> 等价。实现应做大小写无关的查找。</li><li>必须是 <code>token</code>——即不含分隔符与空白。含非法字符的字段名整条报文应拒绝。</li><li>无长度上限规定，实现自设（见<a href="/Front2Full/manual/computer-programming/http11/message-format">报文结构</a>的限制表）。</li></ul><h2 id="field-value-的字符集" tabindex="-1">field-value 的字符集 <a class="header-anchor" href="#field-value-的字符集" aria-label="Permalink to &quot;field-value 的字符集&quot;">​</a></h2><ul><li>合法字符：VCHAR（0x21–0x7E）、SP、HTAB，以及 <code>obs-text</code>（0x80–0xFF）。</li><li><strong>不得</strong>含 CR、LF、NUL。任何在字段值中出现的 CR/LF 都是<strong>头注入（CRLF injection）</strong>，接收方必须拒绝，生成方必须转义或拒绝写入。</li><li><code>obs-text</code> 的字符编码<strong>未定义</strong>。跨语言场景应改用 RFC 8187 的 <code>field*=UTF-8&#39;&#39;...</code> 编码形式（如 <code>Content-Disposition</code> 的 <code>filename*</code>）。</li></ul><h2 id="重复字段的合并" tabindex="-1">重复字段的合并 <a class="header-anchor" href="#重复字段的合并" aria-label="Permalink to &quot;重复字段的合并&quot;">​</a></h2><p><strong>通用规则</strong>：当且仅当该字段的定义是<strong>逗号分隔列表</strong>（<code>#rule</code>）时，多个同名字段行才可合并为一行，反之亦然：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept: text/html</span></span>
<span class="line"><span>Accept: application/json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>等价于：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept: text/html, application/json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>合并时按<strong>接收顺序</strong>用 <code>,</code> 连接，顺序不可打乱——某些字段（如 <code>Via</code>、<code>Forwarded</code>）的顺序承载语义。</p><h3 id="三个例外" tabindex="-1">三个例外 <a class="header-anchor" href="#三个例外" aria-label="Permalink to &quot;三个例外&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>规则</th></tr></thead><tbody><tr><td><code>Set-Cookie</code></td><td><strong>不可合并</strong>。语法含未加引号的逗号（Expires 日期），合并会破坏解析。必须作为多个独立字段行发送与处理</td></tr><tr><td><code>Host</code></td><td>多于一个 → <strong>400</strong></td></tr><tr><td><code>Content-Length</code></td><td>多个且值不一致 → <strong>400</strong>；值一致时可当作单个</td></tr></tbody></table><h2 id="list-based-字段的通用扩展语法" tabindex="-1">list-based 字段的通用扩展语法 <a class="header-anchor" href="#list-based-字段的通用扩展语法" aria-label="Permalink to &quot;list-based 字段的通用扩展语法&quot;">​</a></h2><p>RFC 9110 用 <code>#rule</code> 记法表示逗号分隔列表，展开后允许<strong>空元素</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#element =&gt; [ element ] *( OWS &quot;,&quot; OWS [ element ] )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>因此 <code>Accept: text/html,,application/json</code> 语法合法，接收方<strong>必须忽略空元素</strong>而非报错。生成方不应产生空元素。</p><h2 id="参数-parameters" tabindex="-1">参数（parameters） <a class="header-anchor" href="#参数-parameters" aria-label="Permalink to &quot;参数（parameters）&quot;">​</a></h2><p>大量字段（<code>Content-Type</code>、<code>Accept</code>、<code>Cache-Control</code> 等）复用同一参数语法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>parameters      = *( OWS &quot;;&quot; OWS [ parameter ] )</span></span>
<span class="line"><span>parameter       = parameter-name &quot;=&quot; parameter-value</span></span>
<span class="line"><span>parameter-name  = token</span></span>
<span class="line"><span>parameter-value = ( token / quoted-string )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li>参数名<strong>大小写不敏感</strong>；参数值是否敏感由具体字段定义（如 <code>charset=UTF-8</code> 不敏感，boundary 敏感）。</li><li><code>=</code> 两侧<strong>不允许</strong>有空白（BWS 在部分旧定义中允许，新规范要求生成方不产生）。</li><li>值含 <code>token</code> 之外的字符时必须用 <code>quoted-string</code>。</li></ul><h2 id="quoted-string-与转义" tabindex="-1">quoted-string 与转义 <a class="header-anchor" href="#quoted-string-与转义" aria-label="Permalink to &quot;quoted-string 与转义&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>quoted-string = DQUOTE *( qdtext / quoted-pair ) DQUOTE</span></span>
<span class="line"><span>qdtext        = HTAB / SP / %x21 / %x23-5B / %x5D-7E / obs-text</span></span>
<span class="line"><span>quoted-pair   = &quot;\\&quot; ( HTAB / SP / VCHAR / obs-text )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>引号内的 <code>&quot;</code> 与 <code>\\</code> <strong>必须</strong>用 <code>\\</code> 转义。</li><li>解析时须先去引号再解转义，得到的才是真实值。</li><li><code>quoted-pair</code> 仅在 <code>quoted-string</code> 与 <code>comment</code> 内合法。</li></ul><h2 id="字段的分类" tabindex="-1">字段的分类 <a class="header-anchor" href="#字段的分类" aria-label="Permalink to &quot;字段的分类&quot;">​</a></h2><p>按适用位置分四类，决定字段可出现在何处：</p><table tabindex="0"><thead><tr><th>类别</th><th>出现位置</th><th>例</th></tr></thead><tbody><tr><td>请求字段</td><td>仅请求</td><td><code>Host</code>、<code>Accept</code>、<code>If-Match</code></td></tr><tr><td>响应字段</td><td>仅响应</td><td><code>Server</code>、<code>ETag</code>、<code>WWW-Authenticate</code></td></tr><tr><td>表示字段</td><td>请求或响应，描述消息体</td><td><code>Content-Type</code>、<code>Content-Encoding</code></td></tr><tr><td>逐跳字段</td><td>单个连接内有效，<strong>不得转发</strong></td><td><code>Connection</code>、<code>Transfer-Encoding</code>、<code>Upgrade</code></td></tr></tbody></table><p><strong>逐跳（hop-by-hop）字段</strong>由 <code>Connection</code> 列出，代理必须在转发前移除，见<a href="/Front2Full/manual/computer-programming/http11/connection-management">连接管理</a>。</p><h2 id="trailer-字段" tabindex="-1">Trailer 字段 <a class="header-anchor" href="#trailer-字段" aria-label="Permalink to &quot;Trailer 字段&quot;">​</a></h2><p>分块编码时，部分字段可放在体之后的 trailer 区：</p><ul><li><strong>不得</strong>放入 trailer 的字段：影响成帧的（<code>Transfer-Encoding</code>、<code>Content-Length</code>）、路由的（<code>Host</code>）、请求控制的（<code>Cache-Control</code>、<code>Expect</code>、<code>TE</code>、<code>Authorization</code>）、以及处理需前置的（<code>Content-Encoding</code>、<code>Content-Type</code>、<code>Range</code>）。</li><li>接收方<strong>可以</strong>丢弃全部 trailer；发送方不得把必要语义只放在 trailer 里。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/message-body-length">消息体长度</a>——成帧规则的完整优先级链。</p>`,36)])])}const m=a(o,[["render",d]]);export{h as __pageData,m as default};
